def solve():
    N, M = map(int, input().split())

    # Read all photos
    photos = []
    for _ in range(M):
        photo = list(map(int, input().split()))
        photos.append(photo)

    # Count pairs that may be in bad mood
    bad_mood_pairs = 0

    # Check each pair of people (i, j) where i < j
    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            # Check if i and j were adjacent in any photo
            adjacent_in_some_photo = False

            for photo in photos:
                # Check if i and j are adjacent in this photo
                # Find positions of i and j in the photo
                pos_i = -1
                pos_j = -1

                for idx, person in enumerate(photo):
                    if person == i:
                        pos_i = idx
                    elif person == j:
                        pos_j = idx

                # If both positions are found, check if they are adjacent
                if pos_i != -1 and pos_j != -1:
                    if abs(pos_i - pos_j) == 1:
                        adjacent_in_some_photo = True
                        break

            # If they were never adjacent in any photo, they are in bad mood
            if not adjacent_in_some_photo:
                bad_mood_pairs += 1

    print(bad_mood_pairs)

